import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type CreditGaugeProps = Record<string, any>;

// Helper math for drawing SVG arcs and wedges
function polarToCartesian(centerX: number, centerY: number, radius: number, angleInDegrees: number) {
  const angleInRadians = (angleInDegrees - 90) * Math.PI / 180.0;
  return {
    x: centerX + (radius * Math.cos(angleInRadians)),
    y: centerY + (radius * Math.sin(angleInRadians))
  };
}

function describeArc(x: number, y: number, radius: number, startAngle: number, endAngle: number) {
  const start = polarToCartesian(x, y, radius, startAngle);
  const end = polarToCartesian(x, y, radius, endAngle);
  const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";
  
  return [
    "M", start.x, start.y,
    "A", radius, radius, 0, largeArcFlag, 1, end.x, end.y
  ].join(" ");
}

function describeWedge(x: number, y: number, radius: number, startAngle: number, endAngle: number) {
  const start = polarToCartesian(x, y, radius, startAngle);
  const end = polarToCartesian(x, y, radius, endAngle);
  const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";
  
  return [
    "M", x, y,
    "L", start.x, start.y,
    "A", radius, radius, 0, largeArcFlag, 1, end.x, end.y,
    "Z"
  ].join(" ");
}

const CreditGauge: React.FC<CreditGaugeProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  segmentColors = ["#ccebf8", "#50bcf1", "#1e7cbd", "#0d5182", "#172343"],
  needleColor = "#2ab2ea",
  
  labelLow = "LOW",
  labelLowSize = 3.5,
  labelLowOffsetX = 0,
  labelLowOffsetY = 0,
  
  labelMedium = "MEDIUM",
  labelMediumSize = 3.5,
  labelMediumOffsetX = 0,
  labelMediumOffsetY = 0,
  
  labelHigh = "HIGH",
  labelHighSize = 3.5,
  labelHighOffsetX = 0,
  labelHighOffsetY = 0,
  
  title = "CREDIT QUALITY",
  titleFontSize = 6.0,
  titleOffsetX = 0,
  titleOffsetY = 0,

  labelColor = "#ffffff",
  titleColor = "#ffffff",
  targetPercentage = 85,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Math Setup
  const s = Math.min(width, height);
  const cx = width / 2;
  const cy = height / 2 + s * 0.14;
  const radius = s * 0.37;
  const strokeWidth = radius * 0.28;
  const outerRadius = radius + strokeWidth / 2;

  // Inner Gauge Setup
  const innerRadius = radius - strokeWidth / 2 - s * 0.03;

  const needleLength = radius * 0.9;
  const needleBaseRadius = radius * 0.075;
  const baseWidth = needleBaseRadius * 0.8;
  const needlePoints = `-${baseWidth},0 ${baseWidth},0 0,-${needleLength}`;
  
  const shadowTranslateY = s * 0.015;

  // Text Sizes & Positions
  const actualLabelLowSize = s * (labelLowSize / 100);
  const actualLabelMediumSize = s * (labelMediumSize / 100);
  const actualLabelHighSize = s * (labelHighSize / 100);
  const actualTitleSize = s * (titleFontSize / 100);

  const lowTextX = cx - outerRadius - s * 0.04 + labelLowOffsetX;
  const lowTextY = cy + actualLabelLowSize * 0.3 + labelLowOffsetY;

  const medTextX = cx + labelMediumOffsetX;
  const medTextY = cy - outerRadius - s * 0.04 + labelMediumOffsetY;

  const highTextX = cx + outerRadius + s * 0.04 + labelHighOffsetX;
  const highTextY = cy + actualLabelHighSize * 0.3 + labelHighOffsetY;

  const finalTitleX = cx + titleOffsetX;
  const finalTitleY = cy + actualTitleSize * 1.5 + titleOffsetY;

  // Fixed segments for a balanced 5-tier gauge spanning 180 degrees
  const segmentsData = [
    { start: -90, end: -55.6, color: segmentColors[0] || "#ccc" },
    { start: -53.6, end: -19.2, color: segmentColors[1] || "#ccc" },
    { start: -17.2, end: 17.2, color: segmentColors[2] || "#ccc" },
    { start: 19.2, end: 53.6, color: segmentColors[3] || "#ccc" },
    { start: 55.6, end: 90, color: segmentColors[4] || "#ccc" },
  ];

  // Animations
  const textOpacity = interpolate(frame, [30, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const textYOffset = interpolate(frame, [30, 45], [s * 0.02, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const targetAngle = -90 + (Math.max(0, Math.min(100, targetPercentage)) / 100) * 180;
  
  const needleSpring = spring({
    frame: frame - 25,
    fps,
    config: { damping: 12, mass: 0.8 },
  });
  
  const currentNeedleAngle = interpolate(needleSpring, [0, 1], [-90, targetAngle]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <svg width={width} height={height} style={{ transition: "none" }}>
        
        {/* Active Colored Segments & Inner Wedges */}
        <g style={{ transition: "none" }}>
          {segmentsData.map((seg, i) => {
            const drawStart = 10 + i * 4;
            const drawEnd = drawStart + 20;
            const drawOffset = interpolate(frame, [drawStart, drawEnd], [1, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            const innerOpacity = interpolate(frame, [drawStart, drawEnd], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });

            return (
              <React.Fragment key={`seg-${i}`}>
                <path
                  d={describeWedge(cx, cy, innerRadius, seg.start, seg.end)}
                  fill={seg.color}
                  opacity={innerOpacity}
                  style={{ transition: "none" }}
                />
                <path
                  d={describeArc(cx, cy, radius, seg.start, seg.end)}
                  fill="none"
                  stroke={seg.color}
                  strokeWidth={strokeWidth}
                  strokeLinecap="butt"
                  pathLength="1"
                  strokeDasharray="1"
                  strokeDashoffset={drawOffset}
                  style={{ transition: "none" }}
                />
              </React.Fragment>
            );
          })}
        </g>

        {/* Needle Shadow Group - Rotates on a shifted axis to keep shadow falling uniformly */}
        <g 
          transform={`translate(${cx}, ${cy + shadowTranslateY}) rotate(${currentNeedleAngle})`}
          style={{ transition: "none" }}
        >
          <polygon points={needlePoints} fill="rgba(0,0,0,0.1)" style={{ transition: "none" }} />
          <circle cx="0" cy="0" r={needleBaseRadius} fill="rgba(0,0,0,0.1)" style={{ transition: "none" }} />
        </g>

        {/* Needle Main Group */}
        <g 
          transform={`translate(${cx}, ${cy}) rotate(${currentNeedleAngle})`}
          style={{ transition: "none" }}
        >
          <polygon points={needlePoints} fill={needleColor} style={{ transition: "none" }} />
          <circle cx="0" cy="0" r={needleBaseRadius} fill={needleColor} style={{ transition: "none" }} />
        </g>

        {/* Text Elements overlayed in SVG for precise alignment relative to gauge */}
        <text
          x={lowTextX}
          y={lowTextY}
          fill={labelColor}
          fontSize={actualLabelLowSize}
          fontWeight="bold"
          textAnchor="end"
          opacity={textOpacity}
          transform={`translate(0, ${textYOffset})`}
          letterSpacing="0.05em"
          style={{ transition: "none" }}
        >
          {labelLow}
        </text>

        <text
          x={medTextX}
          y={medTextY}
          fill={labelColor}
          fontSize={actualLabelMediumSize}
          fontWeight="bold"
          textAnchor="middle"
          opacity={textOpacity}
          transform={`translate(0, ${textYOffset})`}
          letterSpacing="0.05em"
          style={{ transition: "none" }}
        >
          {labelMedium}
        </text>

        <text
          x={highTextX}
          y={highTextY}
          fill={labelColor}
          fontSize={actualLabelHighSize}
          fontWeight="bold"
          textAnchor="start"
          opacity={textOpacity}
          transform={`translate(0, ${textYOffset})`}
          letterSpacing="0.05em"
          style={{ transition: "none" }}
        >
          {labelHigh}
        </text>

        <text
          x={finalTitleX}
          y={finalTitleY}
          fill={titleColor}
          fontSize={actualTitleSize}
          fontWeight="900"
          textAnchor="middle"
          opacity={textOpacity}
          transform={`translate(0, ${textYOffset})`}
          letterSpacing="0.05em"
          style={{ transition: "none" }}
        >
          {title}
        </text>
      </svg>
    </AbsoluteFill>
  );
};

export default CreditGauge;